"""Single immersive demo: geometry-only visuals and a guided buyer journey."""
import json
from build import ROOT, t, version_assets
from proforma import data, basic_panel


def page(title, body):
    return version_assets(f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Arquitectura interactiva, selección de viviendas y recorridos 3D. Demo conceptual de Andean Software Lab."><title>{title} · Andean Software Lab</title><link rel="stylesheet" href="/premium.css"><script src="/asset-loader.js" defer></script><script src="/viewer-controls.js" defer></script><script src="/architecture.js" defer></script><script src="/premium.js" defer></script></head><body><a class="skip" href="#main">Saltar al contenido / Skip to content</a><header class="header"><a class="brand" href="/propuesta/">ANDEAN<span>SOFTWARE LAB / REAL ESTATE</span></a><nav aria-label="Principal / Main"><a href="/proyecto/">{t('Explorar','Explore')}</a><a href="/como-funciona/">{t('La experiencia','The experience')}</a><a href="/demo/">{t('Gestión','Management')}</a><a href="/nosotros/">{t('Equipo','Team')}</a><a class="nav-contact" href="/contacto/">{t('Hablemos ↗','Let’s talk ↗')}</a><button id="language" aria-label="Cambiar idioma / Switch language">EN</button></nav></header>{body}<footer><a class="brand" href="/propuesta/">ANDEAN<span>SOFTWARE LAB</span></a><p>{t('Demo conceptual · Proyecto ficticio · Arquitectura 3D ilustrativa','Concept demo · Fictional project · Illustrative 3D architecture')}</p><a href="/contacto/">{t('Creemos la experiencia de tu proyecto ↗','Let’s create your project experience ↗')}</a></footer></body></html>''')


def viewer(hero=False):
    legend=''.join(f'<span><i class="dot" data-state="{k}"></i>{t(es,en)}</span>' for k,es,en in [('available','Disponible','Available'),('reserved','Reservado','Reserved'),('sold','Vendido','Sold')])
    stepper=f'<div class="floor-stepper" id="floor-stepper" hidden><button data-floor-step="1" aria-label="Piso superior / Floor up">↑</button><span><small>{t("PISO","FLOOR")}</small><b id="floor-now">7</b></span><button data-floor-step="-1" aria-label="Piso inferior / Floor down">↓</button></div>' if not hero else ''
    return f'''<div class="scene-wrap {'hero-scene' if hero else ''}" id="scene-wrap"><canvas id="architecture" tabindex="0" aria-label="Modelo arquitectónico 3D. Arrastra para girar, usa las flechas o los botones de zoom."></canvas><div class="scene-top"><span class="live-dot"></span>{t('ARQUITECTURA EN TIEMPO REAL','REAL-TIME ARCHITECTURE')}<span id="scene-name">RESIDENCIA 01</span></div>{stepper}<div class="scene-status" id="scene-status" role="status">{t('Preparando tu visita…','Preparing your visit…')}</div><div class="scene-bottom"><span id="scene-hint">{t('Arrastra para explorar · toca los puntos','Drag to explore · tap the points')}</span><span class="scene-legend" id="scene-legend" hidden>{legend}</span><div><button data-camera="left" aria-label="Girar a la izquierda / Rotate left">↶</button><button data-camera="right" aria-label="Girar a la derecha / Rotate right">↷</button><button data-camera="in" aria-label="Acercar / Zoom in">+</button><button data-camera="out" aria-label="Alejar / Zoom out">−</button><button data-camera="reset" aria-label="Restablecer vista / Reset view">⌂</button></div></div></div>'''


def build():
    d=data(); p=d['projects'][0]
    feed=json.dumps({'sample':True,'project':p,'typologies':d['typologies']},ensure_ascii=False)
    home=page('Demo inmobiliaria',f'''<main id="main"><section class="hero"><div class="hero-copy"><span class="eyebrow">{t('UNA NUEVA FORMA DE VENDER ESPACIOS','A NEW WAY TO SELL SPACES')}</span><h1>{t('Antes de vivirlo.<br><em>Siéntelo.</em>','Before you live it.<br><em>Feel it.</em>')}</h1><p>{t('De la primera mirada al próximo hogar. Una experiencia inmersiva que convierte la arquitectura en una conversación.','From the first look to the next home. An immersive experience that turns architecture into a conversation.')}</p><a class="button" href="/proyecto/">{t('Comenzar la visita','Start your visit')} <span>↗</span></a><div class="hero-foot"><span>01 — 04</span>{t('El edificio. Tu hogar. La vida dentro.','The building. Your home. Life inside.')}</div></div>{viewer(True)}</section><section class="intro"><span class="eyebrow">{t('UN SOLO RECORRIDO. TODA LA EXPERIENCIA.','ONE JOURNEY. THE COMPLETE EXPERIENCE.')}</span><h2>{t('No solo mostrar.<br><em>Hacer imaginar.</em>','More than showing.<br><em>Inspire a possibility.</em>')}</h2><div class="feature-grid"><article><span>01 /</span><h3>{t('Explora la arquitectura','Explore the architecture')}</h3><p>{t('Gira el edificio, descubre sus terrazas y observa cómo cambia con la luz.','Rotate the building, discover its terraces and see how it changes with the light.')}</p></article><article><span>02 /</span><h3>{t('Encuentra tu espacio','Find your space')}</h3><p>{t('Compara pisos, superficies y disponibilidad sin salir de la experiencia.','Compare floors, areas and availability without leaving the experience.')}</p></article><article><span>03 /</span><h3>{t('Entra. Recorre. Conecta.','Enter. Explore. Connect.')}</h3><p>{t('Explora un interior conceptual y envía una consulta con la vivienda elegida.','Explore a concept interior and send an enquiry with your selected home.')}</p></article></div></section><section class="closing"><h2>{t('Tu proyecto merece<br>una primera impresión<br><em>extraordinaria.</em>','Your project deserves<br>an extraordinary<br><em>first impression.</em>')}</h2><a class="button" href="/contacto/">{t('Hablemos de tu proyecto','Let’s talk about your project')} ↗</a></section></main>''')
    steps=[('La arquitectura','Architecture'),('Tu departamento','Your apartment'),('La vida dentro','Life inside'),('El siguiente paso','Your next step')]
    project=page('Residencia 01 · Visita guiada',f'''<main id="main" class="experience"><div class="experience-heading"><div><span class="eyebrow">{t('PROYECTO FICTICIO / VISITA GUIADA','FICTIONAL PROJECT / GUIDED VISIT')}</span><h1>Residencia <em>01.</em></h1></div><p>{t('Un lugar para imaginar tu próxima historia.','A place to imagine your next story.')}</p></div><nav class="journey" aria-label="Pasos de la visita / Visit steps">{''.join(f'<button data-step="{i}" aria-current="{str(i==0).lower()}"><span>0{i+1}</span>{t(*s)}</button>' for i,s in enumerate(steps))}</nav><div class="experience-grid">{viewer()}<aside class="journey-panel"><span class="eyebrow" id="step-label"></span><h2 id="step-title"></h2><p id="step-copy"></p><div id="building-options"><div class="stat-row"><div><strong>12</strong>{t('pisos residenciales','residential floors')}</div><div><strong>72</strong>{t('hogares de ejemplo','sample homes')}</div></div><p class="small">{t('Terrazas privadas · Jardín en altura · Piscina','Private terraces · Rooftop garden · Pool')}</p></div><div id="unit-options" hidden><label>{t('Piso','Floor')}<select id="floor"></select></label><label>{t('Dormitorios','Bedrooms')}<select id="bedrooms"><option value="all" data-es="Todos" data-en="All">Todos</option><option value="0" data-es="Estudio" data-en="Studio">Estudio</option><option value="1">1</option><option value="2">2</option><option value="3">3</option></select></label><label class="check"><input id="available" type="checkbox" checked>{t('Solo disponibles','Available only')}</label><div id="unit-list" class="unit-list"></div></div><div id="interior-options" hidden><div class="interior-summary"><strong id="interior-type"></strong><p id="interior-description"></p></div><div class="room-buttons">{''.join(f'<button data-room="{r}">{t(es,en)}</button>' for r,es,en in [('overview','Vista general','Overview'),('living','Sala','Living'),('kitchen','Cocina','Kitchen'),('bedroom','Dormitorio','Bedroom'),('bedroom2','Dormitorio 2','Bedroom 2'),('bedroom3','Dormitorio 3','Bedroom 3'),('bathroom','Baño','Bathroom'),('terrace','Terraza','Terrace')])}</div><p class="small">{t('Interior conceptual según tipología. Distribución ilustrativa, no un plano exacto de la unidad.','Concept interior for this apartment type. Illustrative layout, not an exact unit floor plan.')}</p></div><div id="contact-options" hidden><p>{t('Elige una vivienda para incluir sus datos en tu consulta. El correo se abre para que lo revises antes de enviarlo.','Choose a home to include its details in your enquiry. Your email opens for review before sending.')}</p><a id="enquire" class="button" href="/contacto/">{t('Preparar mi consulta ↗','Prepare my enquiry ↗')}</a></div><div id="selected-home" class="selected-home" aria-live="polite"></div><div class="journey-actions"><button id="previous" class="text-button">{t('← Atrás','← Back')}</button><button id="next" class="button">{t('Continuar →','Continue →')}</button></div></aside></div><div class="experience-tools"><div class="light-controls" role="group" aria-label="Iluminación / Lighting">{''.join(f'<button data-light="{i}" aria-pressed="{str(i==1).lower()}">{t(es,en)}</button>' for i,(es,en) in enumerate([('Mañana','Morning'),('Atardecer','Sunset'),('Noche','Night')]))}</div><p>{t('Modelo ilustrativo, superficies y disponibilidad de ejemplo. Sin reservas ni pagos.','Illustrative model, sample areas and availability. No reservations or payments.')}</p></div><noscript><p>Activa JavaScript para explorar. Contacto: alvaroipazr@gmail.com.</p></noscript></main><script id="demo-data" type="application/json">{feed}</script>''')
    for route,html in [('',home),('propuesta',home),('proyecto',project),('pixel',project),('comparar',project)]:
        folder=ROOT/route;folder.mkdir(exist_ok=True);(folder/'index.html').write_text(html)
    info=page('La experiencia',f'''<main id="main" class="text-page"><span class="eyebrow">{t('UNA EXPERIENCIA INMERSIVA COMPLETA','ONE COMPLETE IMMERSIVE EXPERIENCE')}</span><h1>{t('Arquitectura.<br>Información.<br><em>Conversación.</em>','Architecture.<br>Information.<br><em>Conversation.</em>')}</h1><div class="feature-grid"><article><h2>{t('Un recorrido conectado','A connected journey')}</h2><p>{t('Exterior 3D, selección de vivienda, interiores navegables y consulta comercial con el contexto de la unidad elegida. Todo forma parte de la misma experiencia.','3D exterior, home selection, navigable interiors and a sales enquiry with the selected unit’s details. All part of the same experience.')}</p></article><article><h2>{t('Diseñado para tu proyecto','Designed for your project')}</h2><p>{t('Partimos de tus planos, inventario y marca. La geometría de esta demo es ilustrativa; el modelo de tu proyecto se prepara y valida con tu equipo.','We start with your plans, inventory and brand. This demo’s geometry is illustrative; your project’s model is prepared and validated with your team.')}</p></article><article><h2>{t('Conectado con tu equipo','Connected to your team')}</h2><p>{t('Definimos las conexiones a tu gestor de contenidos, CRM y WhatsApp según tu proceso comercial. Esta demo usa datos locales y abre una consulta por correo; no conecta todavía con esos servicios.','We define connections to your content manager, CRM and WhatsApp around your sales process. This demo uses local data and opens an email enquiry; it is not yet connected to those services.')}</p></article></div><a class="button" href="/proyecto/">{t('Explorar la experiencia ↗','Explore the experience ↗')}</a></main>''')
    for route in ['como-funciona']:
        (ROOT/route).mkdir(exist_ok=True);(ROOT/route/'index.html').write_text(info)
    tools=page('Gestión y consultas',f'''<main id="main" class="pf text-page"><span class="eyebrow">{t('GESTIÓN Y CONSULTAS','MANAGEMENT & ENQUIRIES')}</span><h1>{t('Un dato.<br><em>Todo conectado.</em>','One update.<br><em>Everything connected.</em>')}</h1><p>{t('Simulación local: cambia el inventario y observa las salidas. Los cambios se reinician al recargar; no se envían mensajes ni se conecta a un CRM.','Local simulation: change the inventory and see the outputs. Changes reset on reload; no messages are sent and no CRM is connected.')}</p><a class="button" href="/proyecto/">{t('Volver a la visita 3D ↗','Back to the 3D visit ↗')}</a>{basic_panel(d).replace('role="tabpanel" aria-labelledby="tab-basico"','aria-label="Gestión y consultas / Management and enquiries"')}</main><script type="application/json" id="demo-data">{json.dumps(d,ensure_ascii=False)}</script><script src="/management.js" defer></script>''')
    tools=tools.replace('<link rel="stylesheet" href="/premium.css', '<link rel="stylesheet" href="/proforma.css"><link rel="stylesheet" href="/premium.css')
    for route in ['demo','proforma']:
        (ROOT/route/'index.html').write_text(version_assets(tools))
    team=page('Nuestro equipo',f'''<main id="main" class="text-page"><span class="eyebrow">ANDEAN SOFTWARE LAB</span><h1>{t('De la visión<br>al <em>producto.</em>','From vision<br>to <em>product.</em>')}</h1><div class="team-grid"><article><span class="monogram">AP</span><h2>Alvaro Paz</h2><p>{t('Ingeniería de software · Frontend y backend','Software engineering · Frontend and backend')}</p><p>React · Node.js · {t('Integraciones','Integrations')}</p><a href="https://www.linkedin.com/in/alvaropaz/" target="_blank" rel="noopener">LinkedIn ↗</a></article><article><span class="monogram">MV</span><h2>Martín Vélez Falconí</h2><p>Backend · {t('Automatización','Automation')} · DevOps</p><p>Django · Odoo · CI/CD · Kubernetes · Azure DevOps</p><a href="https://www.linkedin.com/in/martin-velez-falconi/" target="_blank" rel="noopener">LinkedIn ↗</a></article></div></main>''')
    contact=page('Hablemos',f'''<main id="main" class="text-page"><span class="eyebrow">{t('TU PROYECTO, EL PRÓXIMO RECORRIDO','YOUR PROJECT, THE NEXT JOURNEY')}</span><h1>{t('Hagamos espacio<br>para <em>tu visión.</em>','Make room<br>for <em>your vision.</em>')}</h1><p>{t('Cuéntanos qué estás construyendo, dónde se encuentra y cómo lo estás comercializando. Revisemos juntos los planos, el inventario y la experiencia que necesitan tus compradores.','Tell us what you are building, where it is and how you are selling it. Let’s review your plans, inventory and the experience your buyers need.')}</p><div class="team-grid"><article><h2>Alvaro Paz</h2><a href="mailto:alvaroipazr@gmail.com?subject=Experiencia%20inmobiliaria%203D">alvaroipazr@gmail.com ↗</a></article><article><h2>Martín Vélez Falconí</h2><a href="mailto:martinvelezf@hotmail.com?subject=Experiencia%20inmobiliaria%203D">martinvelezf@hotmail.com ↗</a></article></div><a class="text-button" href="/proyecto/">{t('Volver a la visita','Back to the visit')} →</a></main>''')
    for route,html in [('nosotros',team),('contacto',contact)]:
        (ROOT/route).mkdir(exist_ok=True);(ROOT/route/'index.html').write_text(html)

if __name__=='__main__':build()
